    $link->loseAck=true;require_once AF_ADDONS.'advancedcombatsystem/modules/Application/RecoveryService.php';$r=(new AF_ACS_RecoveryService($db,$access))->recover($parent['submission_id'],$parent['state_version']);snapshot_assert($r['mechanics_confirmed'],'Hidden execution ACK recovery');$after=$captureAll();$execution=json_decode($after['prepared_executions'][0]['result_json'],true);snapshot_assert($execution['outcome']==='executed'&&$after['rolls']===$armed['rolls'],'Hidden execution rerolled');
